@unittest.skipUnless(os.name == "posix", "needs fd 2 closed before startup")
class StderrFailureTests(CliCase):
    """The exit status holds when the error message cannot be delivered."""

    def run_pw(self, argv, stderr_arg=None, close_stderr=False):
        env = dict(os.environ, PYTHONPATH=ROOT)
        kwargs = {}
        if close_stderr:
            kwargs["preexec_fn"] = lambda: os.close(2)
        else:
            kwargs["stderr"] = stderr_arg
        return subprocess.run(
            [sys.executable, "-m", "pennywise", *argv],
            stdout=subprocess.PIPE, env=env, cwd=self.dir, **kwargs
        )

    def bad(self):
        return self.write("bad.txt", "bad\\n")

    def test_closed_stderr_missing_file(self):
        r = self.run_pw(["balance", "missing.txt"], close_stderr=True)
        self.assertEqual(r.returncode, 2)

    def test_closed_stderr_bad_ledger(self):
        r = self.run_pw(["balance", self.bad()], close_stderr=True)
        self.assertEqual(r.returncode, 1)

    def test_closed_stderr_usage_error(self):
        r = self.run_pw(["nosuchcommand"], close_stderr=True)
        self.assertEqual(r.returncode, 2)

    @unittest.skipUnless(os.path.exists("/dev/full"), "no /dev/full here")
    def test_full_stderr_missing_file(self):
        with open("/dev/full", "wb") as full:
            r = self.run_pw(["balance", "missing.txt"], full)
        self.assertEqual(r.returncode, 2)

    @unittest.skipUnless(os.path.exists("/dev/full"), "no /dev/full here")
    def test_full_stderr_bad_ledger(self):
        with open("/dev/full", "wb") as full:
            r = self.run_pw(["balance", self.bad()], full)
        self.assertEqual(r.returncode, 1)

    @unittest.skipUnless(os.path.exists("/dev/full"), "no /dev/full here")
    def test_full_stderr_usage_error(self):
        with open("/dev/full", "wb") as full:
            r = self.run_pw(["nosuchcommand"], full)
        self.assertEqual(r.returncode, 2)

    def test_stderr_none_in_process(self):
        with mock.patch.object(sys, "stderr", None):
            self.assertEqual(cli.main(["balance", "missing.txt"]), 2)
            self.assertEqual(cli.main(["balance", self.bad()]), 1)
